        public static UnitConverterMassUnit[] GetUnitsForSystem(UnitConverterUnitSystem system)
        {
            var units = new List<UnitConverterMassUnit>();
            for (int i = 0; i < 60; i++) if (GetUnitSystem((UnitConverterMassUnit)i) == system) units.Add((UnitConverterMassUnit)i);
            return units.ToArray();
        }

        public static IReadOnlyList<UnitConverterUnitInfo> GetUnits() { return Metadata.Units; }
        public static UnitConverterUnitInfo GetUnitInfo(UnitConverterMassUnit unit) { Validate(unit); return Metadata.Units[(int)unit]; }
        public static string GetSymbol(UnitConverterMassUnit unit, IFormatProvider provider) { return GetUnitInfo(unit).GetSymbol(provider); }

        public static bool TryParseUnit(string text, out UnitConverterMassUnit unit, IFormatProvider provider = null)
        {
            int id; bool success = UnitConverterText.TryUnit(text, GetUnits(), provider, out id);
            unit = success ? (UnitConverterMassUnit)id : default(UnitConverterMassUnit); return success;
        }

        public static UnitConverterMassUnit ParseUnit(string text, IFormatProvider provider = null)
        {
            UnitConverterMassUnit unit;
            if (!TryParseUnit(text, out unit, provider)) throw new FormatException("Unknown or ambiguous Mass unit: " + text);
            return unit;
        }

        public static bool TryParse(string text, out UnitConverterMassValue quantity, IFormatProvider provider = null)
        {
            double value; int id;
            bool success = UnitConverterText.TryValue(text, GetUnits(), provider, out value, out id);
            quantity = success ? new UnitConverterMassValue(value, (UnitConverterMassUnit)id) : default(UnitConverterMassValue); return success;
        }

        public static UnitConverterMassValue Parse(string text, IFormatProvider provider = null)
        {
            UnitConverterMassValue quantity;
            if (!TryParse(text, out quantity, provider)) throw new FormatException("Expected a finite number and an unambiguous Mass unit.");
            return quantity;
        }

        public static string Format(double value, UnitConverterMassUnit unit, string format = "G", IFormatProvider provider = null)
        {
            return value.ToString(format, provider ?? CultureInfo.CurrentCulture) + " " + GetSymbol(unit, provider);
        }


